import {museumGalleries} from './district-layout.js';
import {closeDialog} from './ui-motion.js';
import {fallbackTrivia} from './trivia-fallback.js';
import {dailyQuestions,galleryQuestions,loadTrivia} from './trivia-loader.js';
let catalog=fallbackTrivia;export const trivia=fallbackTrivia.map(q=>[q.question,q.options,q.answer,q.explanation,'✦',q.source,q.id]);
// Reviewed questions require the anonymous session; loading them before join
// returned 401 and left a fresh guest on the fallback catalog.
let ready=Promise.resolve();
function refreshTrivia(){ready=loadTrivia().then(items=>{catalog=items;});}
if(window.labSocialJoined)refreshTrivia();
window.addEventListener('lab:room',refreshTrivia);
window.addEventListener('lab:quiz-updated',refreshTrivia);
const dialog=document.createElement('dialog');dialog.id='quick-quiz';dialog.setAttribute('aria-labelledby','quick-question');
dialog.innerHTML='<div class="quiz-header"><span>별빛 만물관</span><button class="icon-button" aria-label="퀴즈 닫기"><svg viewBox="0 0 24 24"><path d="m7 7 10 10M17 7 7 17"/></svg></button></div><h2 id="quick-question"></h2><div class="quiz-options"></div><div class="quiz-result" role="status" hidden></div><div class="quiz-footer"><span class="quiz-count"></span><button class="quiz-next" hidden>다음 <svg viewBox="0 0 24 24"><path d="M5 12h14m-5-5 5 5-5 5"/></svg></button></div>';
document.body.append(dialog);let order=[],index=0,score=0,answered=false,gallery=null,requestedQuestion=null;
function render(){answered=false;dialog.classList.remove('quiz-correct','quiz-wrong');const [question,options]=trivia[order[index]];dialog.querySelector('#quick-question').textContent=question;const choices=dialog.querySelector('.quiz-options');choices.replaceChildren();options.forEach((text,i)=>{const b=document.createElement('button');b.textContent=text;b.onclick=()=>answer(i);choices.append(b);});dialog.querySelector('.quiz-result').hidden=true;dialog.querySelector('.quiz-next').hidden=true;dialog.querySelector('.quiz-count').textContent=`${index+1} / ${order.length} · ${score} 정답`;}
function answer(choice){if(answered)return;answered=true;const [,,correct,explanation]=trivia[order[index]],ok=choice===correct;if(ok)score++;[...dialog.querySelector('.quiz-options').children].forEach((b,i)=>{b.disabled=true;b.classList.toggle('correct',i===correct);b.classList.toggle('wrong',i===choice&&!ok);});const result=dialog.querySelector('.quiz-result'),title=document.createElement('strong');title.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${ok?'m5 12 4 4L19 6':'m7 7 10 10M17 7 7 17'}"/></svg><span>${ok?'정답!':'오답'}</span>`;result.replaceChildren(title,document.createTextNode(explanation));const source=trivia[order[index]][5];if(source){const link=document.createElement('a');link.className='quiz-source';link.textContent=source.title+' ↗';link.href=source.url;link.target='_blank';link.rel='noreferrer';result.append(link);const more=document.createElement('button');more.textContent='더 알아보기';more.onclick=()=>window.explainQuiz?.(trivia[order[index]][6],result);result.append(more);}result.hidden=false;dialog.querySelector('.quiz-next').hidden=false;dialog.querySelector('.quiz-next').textContent=index===order.length-1?'한 번 더 ↗':'다음 →';dialog.querySelector('.quiz-count').textContent=`${index+1} / ${order.length} · ${score} 정답`;window.labSound?.(ok?'correct':'wrong');window.dispatchEvent(new CustomEvent('lab:vfx',{detail:{kind:ok?'correct':'wrong',strength:.8}}));dialog.classList.remove('quiz-correct','quiz-wrong');dialog.classList.add(ok?'quiz-correct':'quiz-wrong');if(ok){window.dispatchEvent(new CustomEvent('lab:exhibit-correct',{detail:gallery}));}}
function reset(){const categories=museumGalleries.find(g=>g.id===gallery)?.categories;let questions=categories?galleryQuestions(catalog,categories):dailyQuestions(catalog);const requested=catalog.find(q=>q.id===requestedQuestion&&(!categories||categories.includes(q.category)));if(requested)questions=[requested,...questions.filter(q=>q.id!==requested.id)];requestedQuestion=null;trivia.splice(0,trivia.length,...questions.map(q=>[q.question,q.options,q.answer,q.explanation,'✦',q.source,q.id]));order=trivia.map((_,i)=>i);index=score=0;render();}
window.openQuickQuiz=async(options={})=>{requestedQuestion=options.questionId;gallery=museumGalleries.some(g=>g.id===options.gallery)?options.gallery:null;dialog.querySelector('.quiz-header>span').textContent=museumGalleries.find(g=>g.id===gallery)?.name||'별빛 만물관';window.dispatchEvent(new CustomEvent('lab:exhibit-focus',{detail:gallery}));if(!dialog.open)dialog.showModal();document.body.classList.add('quiz-open');window.dispatchEvent(new Event('lab:pause'));dialog.querySelector('#quick-question').textContent='문제 불러오는 중…';await ready;if(!dialog.open)return;reset();window.labSound?.('quiz');};
dialog.querySelector('.icon-button').onclick=()=>closeDialog(dialog);dialog.querySelector('.quiz-next').onclick=()=>{if(++index===order.length)reset();else render();};dialog.addEventListener('close',()=>{document.body.classList.remove('quiz-open');window.dispatchEvent(new Event('lab:exhibit-close'));window.dispatchEvent(new Event('lab:close'));});


dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog(dialog);});
